import{_ as t,o as a,c as r,a5 as o}from"./chunks/framework.BF53ZjCA.js";const p=JSON.parse('{"title":"Color Centers","description":"","frontmatter":{"title":"Color Centers","colorCause":"color-centers"},"headers":[],"relativePath":"classification/color-causes/color-centers.md","filePath":"classification/color-causes/color-centers.md","lastUpdated":1790876393000}'),n={name:"classification/color-causes/color-centers.md"};function i(l,e,s,c,d,m){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="color-centers" tabindex="-1">Color Centers <a class="header-anchor" href="#color-centers" aria-label="Permalink to &quot;Color Centers&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Color centers are point defects in a crystal lattice that selectively absorb visible light. When an ion is missing (vacancy), extra (interstitial), or substituted by an impurity, nearby electrons or holes become trapped. Their energy levels often fall in the visible range, producing color. Color centers form naturally via radiation, or via artificial irradiation (which may fade with sunlight exposure — a key tell for treated material).</p><h2 id="mechanism" tabindex="-1">Mechanism <a class="header-anchor" href="#mechanism" aria-label="Permalink to &quot;Mechanism&quot;">​</a></h2><p>Common color-center types:</p><ul><li><strong>F-centers</strong> (anion vacancy trapping an electron): typical in fluorite and halite (rock salt)</li><li><strong>V-centers</strong> (cation vacancy trapping a hole): purple quartz (amethyst)</li><li><strong>Impurity centers</strong>: vacancy adjacent to a dopant ion, e.g. Fe⁴⁺ in amethyst Color centers can form rapidly under laboratory irradiation, but natural color centers accumulate over millions of years. Detection of irradiated gems often relies on characteristic short-wave UV luminescence signatures.</li></ul><h2 id="example-gemstones" tabindex="-1">Example Gemstones <a class="header-anchor" href="#example-gemstones" aria-label="Permalink to &quot;Example Gemstones&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Gem</th><th>Defect</th><th>Host</th><th>Color</th></tr></thead><tbody><tr><td>Amethyst / 紫晶</td><td>Fe⁴⁺ color center</td><td>SiO₂</td><td>violet</td></tr><tr><td>Smoky Quartz / 烟晶</td><td>Al impurity + e⁻</td><td>SiO₂</td><td>brown</td></tr><tr><td>Citrine / 黄水晶</td><td>Fe³⁺ color center</td><td>SiO₂</td><td>yellow</td></tr><tr><td>Fluorite / 萤石</td><td>F-center (vacancy)</td><td>CaF₂</td><td>purple / blue</td></tr><tr><td>Yellow Diamond / 黄钻</td><td>N + vacancy (H3)</td><td>C (diamond)</td><td>yellow</td></tr><tr><td>Pink Diamond / 粉钻</td><td>N + plastic deformation</td><td>C (diamond)</td><td>pink</td></tr></tbody></table><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">References &amp; Evidence Boundary</h2><p class="gem-reference-block__intro">This page supports learning and retrieval; the sources document the knowledge basis and do not make this page sufficient for identifying a specific specimen.</p><ul><li><a href="https://www.gia.edu/gems-gemology" target="_blank" rel="noreferrer">GIA: Gems &amp; Gemology research</a><span>Gem color, optical appearance, and gemological research context</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/gems-gemology/summer-2025-phenomenal-gemstones" target="_blank" rel="noreferrer">GIA: Structures Behind the Spectacle</a><span>Structural optical color and microstructure observation clues</span><small>Open source ↗</small></li></ul></aside><p><em>See the <a href="./intro.html">color cause overview</a>.</em></p>',10)])])}const u=t(n,[["render",i]]);export{p as __pageData,u as default};
